"""Read-only graphical review of the applied isolated 54-row speaker map."""
from pathlib import Path
import hashlib
import html
import json
import sqlite3

checkout = Path(__file__).resolve().parents[1]
root = checkout / "output" / "mark4-donor-20261024"
project = "a5a40890-8bb0-4856-aacb-1dcad97074bb"
dbpath = root / "db" / "heartword.sqlite"
manifest = json.loads((root / "assets" / "source-listening-review" / project / "speech-manifest.json").read_text(encoding="utf8"))
receipt = json.loads((root / "review" / "meyah-mark4-speech-binding-applied.json").read_text(encoding="utf8"))
with sqlite3.connect(f"file:{dbpath}?mode=ro", uri=True) as db:
    rows = db.execute("SELECT start_ms,end_ms,verse_ref,speaker_character_id FROM audio_segments WHERE project_id=? AND layer='original_reading' ORDER BY start_ms,id", (project,)).fetchall()
    checks = db.execute("PRAGMA quick_check").fetchone()[0]
if checks != "ok" or len(rows) != 54 or rows[0][0] != 0 or rows[-1][1] != 805685:
    raise SystemExit("Isolated speaker map is incomplete")
for left, right in zip(rows, rows[1:]):
    if left[1] != right[0]:
        raise SystemExit("Speaker map has a gap or overlap")
speaker = {"b78bed54-1d53-4b9f-9070-549dddb71b19": "Jesus", "9cbc4222-b194-4db4-baa9-2ba7083e31f3": "Peter"}
data = [{"index": i+1, "start": a, "end": b, "verse": verse or "Chapter heading", "speaker": speaker.get(who, "Original Meyah"), "kind": "jesus" if who == next(iter(speaker)) else "peter" if who else "original"} for i,(a,b,verse,who) in enumerate(rows)]
speech_link = f"/api/projects/{project}/source-listening-review?scope=speech"
verse_link = f"/api/projects/{project}/source-listening-review?scope=verse"
audio_url = "/media/" + "/".join(manifest["pcmPath"].replace("\\", "/").split("/"))
payload = json.dumps(data, separators=(",", ":"))
cards = "".join(f'<button class="row {d["kind"]}" data-index="{d["index"]}" aria-label="Play row {d["index"]}, {html.escape(d["verse"])}"><span class="num">{d["index"]:02d}</span><strong>{html.escape(d["verse"])}</strong><span>{html.escape(d["speaker"])}</span><small>{d["start"]/1000:.3f}–{d["end"]/1000:.3f} s</small><span class="play">▶ Play row</span></button>' for d in data)
page = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Meyah Mark 4 · speaker map review</title><style>
*{{box-sizing:border-box}}body{{margin:0;background:#f5f2e9;color:#162c35;font:16px/1.45 system-ui,sans-serif}}header{{background:#163a43;color:#fff;padding:2rem max(1.25rem,calc((100vw - 1200px)/2))}}h1{{font-size:2.2rem;margin:.2rem 0}}header p{{max-width:75ch}}main{{max-width:1200px;margin:auto;padding:1.25rem}}a{{color:#a7e3ff}}main a{{color:#0a607b}}.meta{{display:flex;gap:1rem;flex-wrap:wrap}}.meta b{{font-size:1.35rem}}.callout{{background:#fff;border-left:5px solid #d39824;padding:1rem 1.25rem;margin:1.25rem 0}}.timeline{{display:flex;height:42px;overflow:hidden;border:2px solid #163a43;border-radius:7px;background:white}}.timeline span{{height:100%;min-width:1px;cursor:pointer}}.timeline .jesus{{background:#147f9c}}.timeline .peter{{background:#b75f30}}.timeline .original{{background:#ddcfa9}}.legend{{display:flex;gap:1rem;flex-wrap:wrap;margin:.6rem 0 1.3rem}}.legend i{{display:inline-block;width:12px;height:12px;margin-right:.3rem}}.grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:.65rem}}.row{{display:flex;flex-direction:column;align-items:flex-start;text-align:left;gap:.1rem;padding:.8rem;border:1px solid #aaa;border-left:7px solid;background:#fff;border-radius:5px;color:#162c35;cursor:pointer}}.row:hover,.row.active{{outline:2px solid #193a45}}.row.jesus{{border-left-color:#147f9c}}.row.peter{{border-left-color:#b75f30}}.row.original{{border-left-color:#ddcfa9}}.row .num{{font-weight:700;font-size:.8rem}}.row strong{{font-size:1.1rem}}.row small{{color:#52656b}}.play{{margin-top:.3rem;color:#005d79;font-weight:700}}.player{{position:sticky;top:0;z-index:2;background:#fff;border-bottom:2px solid #163a43;padding:.8rem max(1rem,calc((100vw - 1200px)/2));display:flex;align-items:center;gap:1rem;flex-wrap:wrap}}audio{{max-width:100%}}button{{font:inherit}}#stop{{padding:.4rem .7rem}}@media(max-width:700px){{header{{padding:1.2rem}}h1{{font-size:1.7rem}}}}
</style></head><body><header><div class="meta"><span><b>Markus 4</b> · Meyah</span><span>Isolated source binding · 25 October 2026</span></div><h1>Review the speaker map</h1><p>Dan approved applying this 54-row map at the previously verified quotation edges. Select any row to hear that exact span of the original Meyah recording. Blue is mapped Jesus speech; orange is mapped Peter speech; cream stays in the original Meyah performance.</p></header><div class="player"><strong id="playing">Select a row to listen</strong><audio id="audio" controls preload="metadata" src="{html.escape(audio_url)}"></audio><button id="stop">Stop</button><span id="clock"></span></div><main><div class="callout"><strong>Review decision needed:</strong> Does this speaker map correctly separate Jesus and Peter from the surrounding narration? Pay special attention to 4:35 and 4:38. The 4:39 action and 4:41 group question retain the original Meyah performance. <a href="{speech_link}">Open exact speech windows and waveform</a> · <a href="{verse_link}">Open the earlier 40-row verse archive</a>. Internal verse edges remain approximate.</div><div class="timeline" id="timeline" aria-label="Whole-chapter speaker timeline"></div><div class="legend"><span><i style="background:#147f9c"></i>Jesus mapped voice</span><span><i style="background:#b75f30"></i>Peter mapped voice</span><span><i style="background:#ddcfa9"></i>Original Meyah</span></div><p><b>54 rows</b> cover 0:00.000–13:25.685 without gaps. Jesus: <b>561.242 s</b>; Peter: <b>8.281 s</b>. Source SHA256 <code>{receipt["sourceHash"]}</code>. Binding ID <code>{receipt["recordId"]}</code>.</p><div class="grid" id="grid">{cards}</div></main><script>
const rows={payload};const audio=document.querySelector('#audio'),label=document.querySelector('#playing'),clock=document.querySelector('#clock');let selected=null;const fmt=s=>`${{Math.floor(s/60)}}:${{String(Math.floor(s%60)).padStart(2,'0')}}.${{String(Math.round((s%1)*1000)).padStart(3,'0')}}`;function stop(){{audio.pause();selected=null;document.querySelectorAll('.row.active').forEach(e=>e.classList.remove('active'));}}async function play(index){{const row=rows[index-1];if(!row)return;stop();selected=row;const el=document.querySelector(`[data-index="${{index}}"]`);el.classList.add('active');el.scrollIntoView({{block:'nearest'}});label.textContent=`Row ${{index}} · ${{row.verse}} · ${{row.speaker}}`;audio.currentTime=row.start/1000;try{{await audio.play();}}catch(e){{label.textContent='Press play in the audio control to hear this row.';}}}}document.querySelectorAll('.row').forEach(e=>e.addEventListener('click',()=>play(Number(e.dataset.index))));document.querySelector('#stop').addEventListener('click',stop);audio.addEventListener('timeupdate',()=>{{clock.textContent=fmt(audio.currentTime);if(selected&&audio.currentTime>=selected.end/1000)stop();}});const timeline=document.querySelector('#timeline');for(const row of rows){{const el=document.createElement('span');el.className=row.kind;el.style.flex=`${{row.end-row.start}} 0 0`;el.title=`${{row.verse}} · ${{row.speaker}} · ${{fmt(row.start/1000)}}–${{fmt(row.end/1000)}}`;el.addEventListener('click',()=>play(row.index));timeline.append(el);}}
</script></body></html>'''
destination = root / "assets" / "review" / "meyah-mark4-speech-binding-20261025" / "index.html"
destination.parent.mkdir(parents=True, exist_ok=True)
destination.write_text(page, encoding="utf8")
print(destination)
print("SHA256", hashlib.sha256(destination.read_bytes()).hexdigest())
